//! PyO3 bindings generated by rust-anything, adapted to borrow pixel buffers.
//! `rust-anything refresh` overwrites the byte adapters in this file.
#![forbid(unsafe_code)]

use pyo3::prelude::*;
use pyo3::types::{PyBytes, PyBytesMethods};

pub mod js;
pub mod port;
pub mod pyconv;
pub mod pynum;

fn error(message: String) -> PyErr {
    let text = message.strip_prefix("ValueError: ").unwrap_or(&message);
    pyo3::exceptions::PyValueError::new_err(text.to_owned())
}

fn bytes<'a>(value: &'a Bound<'_, PyAny>) -> PyResult<&'a [u8]> {
    value
        .cast::<PyBytes>()
        .map(PyBytesMethods::as_bytes)
        .map_err(|_| error(port::BUFFER.into()))
}

#[pyfunction]
fn outside_mask_diff(
    orig_rgb: Bound<'_, PyAny>,
    clean_rgb: Bound<'_, PyAny>,
    mask_l: Bound<'_, PyAny>,
    width: i64,
    height: i64,
    threshold: i64,
) -> PyResult<Vec<i64>> {
    port::outside_mask_diff(
        bytes(&orig_rgb)?,
        bytes(&clean_rgb)?,
        bytes(&mask_l)?,
        width,
        height,
        threshold,
    )
    .map_err(error)
}

#[pyfunction]
fn changed_mask_rgb<'py>(
    py: Python<'py>,
    a_rgb: Bound<'py, PyAny>,
    b_rgb: Bound<'py, PyAny>,
    width: i64,
    height: i64,
    threshold: i64,
) -> PyResult<Bound<'py, PyBytes>> {
    let mask = port::changed_mask_rgb(bytes(&a_rgb)?, bytes(&b_rgb)?, width, height, threshold)
        .map_err(error)?;
    Ok(PyBytes::new(py, &mask))
}

#[pyfunction]
fn overlap_changed_pixels(
    changed_mask: Bound<'_, PyAny>,
    width: i64,
    height: i64,
    boxes: Bound<'_, PyAny>,
) -> PyResult<Vec<Vec<i64>>> {
    port::overlap_changed_pixels(
        bytes(&changed_mask)?,
        width,
        height,
        pyconv::from_py(&boxes).map_err(error)?,
    )
    .map_err(error)
}

#[pyfunction]
#[expect(
    clippy::too_many_arguments,
    reason = "The Python API takes nine arguments"
)]
fn outline_crossing_pixels(
    orig_rgb: Bound<'_, PyAny>,
    clean_rgb: Bound<'_, PyAny>,
    final_rgb: Bound<'_, PyAny>,
    safe_mask: Bound<'_, PyAny>,
    width: i64,
    height: i64,
    r#box: Bound<'_, PyAny>,
    dark_polarity: bool,
    diff_threshold: i64,
) -> PyResult<i64> {
    port::outline_crossing_pixels(
        bytes(&orig_rgb)?,
        bytes(&clean_rgb)?,
        bytes(&final_rgb)?,
        bytes(&safe_mask)?,
        width,
        height,
        pyconv::from_py(&r#box).map_err(error)?,
        dark_polarity,
        diff_threshold,
    )
    .map_err(error)
}

#[pymodule]
#[pyo3(name = "_native")]
fn native_module(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(outside_mask_diff, m)?)?;
    m.add_function(wrap_pyfunction!(changed_mask_rgb, m)?)?;
    m.add_function(wrap_pyfunction!(overlap_changed_pixels, m)?)?;
    m.add_function(wrap_pyfunction!(outline_crossing_pixels, m)?)?;
    Ok(())
}
